/* Host tests for the software PGF decoder in engine/font/pgf.c.
 *
 * assets/test.pgf is generated by tools/gen_pgf_fixture.py and is a small
 * synthetic revision 2 PGF: 'A'/'B' ('D') are 6x8 row-major bitmaps, 'C' is a
 * 4x5 column-major one, 'D' stores its metrics through the index tables and
 * 'Z' is mapped outside the glyph table so the decoder must treat it as
 * missing.
 */
#include "engine/font/font.h"

#include <stdio.h>

static int checks;
static int fails;

static void check(int cond, const char *msg)
{
    checks++;
    if (!cond) {
        fails++;
        printf("  FAIL: %s\n", msg);
    }
}

extern int font_stub_blits;
extern OL_Surface *font_stub_last_surface;
extern int font_stub_last_x, font_stub_last_y;
extern int font_stub_last_sx, font_stub_last_sy;
extern int font_stub_last_sw, font_stub_last_sh;
extern unsigned int font_stub_last_tint;

static unsigned int atlas_pixel(int x, int y)
{
    if (!font_stub_last_surface)
        return 0;
    return font_stub_last_surface->pixels[
        (size_t)y * (size_t)font_stub_last_surface->realW + (size_t)x];
}

int main(int argc, char **argv)
{
    const char *assets = argc > 1 ? argv[1] : "../assets";
    char path[512], missing[512], rev3[512], trunc[512], notpgf[512];

    snprintf(path, sizeof(path), "%s/test.pgf", assets);
    snprintf(missing, sizeof(missing), "%s/missing.pgf", assets);
    snprintf(rev3, sizeof(rev3), "%s/test-rev3.pgf", assets);
    snprintf(trunc, sizeof(trunc), "%s/test-truncated.pgf", assets);
    snprintf(notpgf, sizeof(notpgf), "%s/test_sheet.png", assets);

    check(font_alloc_pgf(NULL) == 0, "NULL PGF path returns 0");
    check(font_alloc_pgf(missing) == 0, "missing PGF returns 0");
    check(font_alloc_pgf(notpgf) == 0, "non-PGF file returns 0");
    check(font_alloc_pgf(rev3) == 0, "revision 3 PGF is rejected");
    check(font_alloc_pgf(trunc) == 0, "truncated PGF is rejected");

    int f = font_alloc_pgf(path);
    check(f > 0, "synthetic revision 2 PGF decodes");
    check(font_nchars(f) == 95, "PGF exposes printable ASCII");
    check(font_cellh(f) == 18, "line height comes from maxBaseY/maxDescender");
    check(font_textheight(f) == 8, "text height is the glyph ink span");
    check(font_cellw(f) == 6, "cell width comes from the widest advance");

    check(font_textwidth("AB", f) == 12, "text width sums 26.6 advances");
    check(font_textwidth("D", f) == 5, "indexed metrics are honoured");
    check(font_textwidth(" ", f) == 4, "space has its own advance");
    check(font_textwidth("\t", f) == 16, "tab advances four spaces");
    check(font_textwidth("Z", f) == 0, "glyph mapped outside the table is absent");
    check(font_textwidth_scaled("AB", f, 0.5f) == 6, "scaled width halves");

    /* Row-major glyphs: 'A' is packed at the atlas origin, 'B' right after it
     * and both sit on the baseline reported by maxBaseYAdjust. */
    int before = font_stub_blits;
    int endx = font_draw_text(f, 10, 20, "AB", 0xFFFFFFFFu);
    check(endx == 22, "draw_text returns the final X cursor");
    check(font_stub_blits == before + 2, "draw_text emits one blit per glyph");
    check(font_stub_last_surface && font_stub_last_surface->w <= 512 &&
          font_stub_last_surface->h <= 512,
          "atlas stays within the 512px GE texture limit");
    check(font_stub_last_sw == 6 && font_stub_last_sh == 8,
          "glyph source rectangle matches the bitmap");
    check(font_stub_last_sx == 7 && font_stub_last_sy == 0,
          "'B' is packed after 'A'");
    check(font_stub_last_x == 17 && font_stub_last_y == 24,
          "bearing and baseline place the glyph");
    check(font_stub_last_tint == 0xFFFFFFFFu, "draw_text forwards the tint");

    before = font_stub_blits;
    font_draw_glyph(f, 10, 20, 'A', 0xFFFFFFFFu);
    check(font_stub_blits == before + 1, "single glyph draws once");
    check(font_stub_last_sx == 0 && font_stub_last_sy == 0,
          "'A' starts at the atlas origin");
    check(font_stub_last_x == 11 && font_stub_last_y == 24,
          "single glyph applies bearing and baseline");

    /* RLE expansion: pixel value is (x + y) & 15, stored as 4-bit coverage. */
    check(atlas_pixel(0, 0) == 0x00FFFFFFu, "zero coverage becomes transparent");
    check(atlas_pixel(1, 0) == 0x11FFFFFFu, "coverage expands to white alpha");
    check(atlas_pixel(5, 7) == 0xCCFFFFFFu, "last pixel of 'A' decodes");

    /* Column-major glyph. */
    font_draw_glyph(f, 0, 0, 'C', 0xFFFFFFFFu);
    check(font_stub_last_sx == 14 && font_stub_last_sy == 0,
          "column-major glyph packed after 'B'");
    check(font_stub_last_sw == 4 && font_stub_last_sh == 5,
          "column-major glyph keeps its size");
    check(atlas_pixel(14 + 2, 3) == 0xEEFFFFFFu,
          "column-major bitmap is transposed back");

    /* Index-table glyph. */
    font_draw_glyph(f, 0, 0, 'D', 0xFFFFFFFFu);
    check(font_stub_last_sx == 19 && font_stub_last_sw == 6,
          "index-table glyph packed after 'C'");

    before = font_stub_blits;
    endx = font_draw_text(f, 0, 0, "Z", 0xFFFFFFFFu);
    check(endx == 0 && font_stub_blits == before,
          "absent glyph draws nothing and advances nothing");

    endx = font_draw_text_scaled(f, 10, 20, "AB", 0xFFFFFFFFu, 0.5f);
    check(endx == 16, "scaled draw returns the scaled X cursor");

    font_free(f);
    check(font_nchars(f) == 0, "PGF handle is released");

    printf("pgf C: %d checks, %d failure(s)\n", checks, fails);
    return fails ? 1 : 0;
}
